import{_ as s,o as e,c as r,ai as a}from"./chunks/framework.Ba-VnP44.js";const c=JSON.parse('{"title":"ERP 核心问题清单","description":"","frontmatter":{},"headers":[],"relativePath":"scenarios/enterprise-digital/erp.md","filePath":"scenarios/enterprise-digital/erp.md"}'),n={name:"scenarios/enterprise-digital/erp.md"};function i(o,t,d,l,p,g){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h1 id="erp-核心问题清单" tabindex="-1">ERP 核心问题清单 <a class="header-anchor" href="#erp-核心问题清单" aria-label="Permalink to “ERP 核心问题清单”">​</a></h1><blockquote><p><strong>一句话定位</strong>：ERP 管的是&quot;该做什么、值多少钱&quot;——把订单变成计划，把计划变成单据，把单据变成钱。</p><p><strong>本文用途</strong>：把 ERP 最容易崩的 10 个环节列清楚，每个给出成因、解法与面试口径。配套：<a href="/my-vitepress-site/scenarios/enterprise-digital/wms.html">WMS</a> · <a href="/my-vitepress-site/scenarios/enterprise-digital/mes.html">MES</a> · <a href="/my-vitepress-site/scenarios/enterprise-digital/iiot.html">IIoT</a>。</p></blockquote><h2 id="一、erp-到底在算什么" tabindex="-1">一、ERP 到底在算什么 <a class="header-anchor" href="#一、erp-到底在算什么" aria-label="Permalink to “一、ERP 到底在算什么”">​</a></h2><p>三件事，按顺序：</p><ol><li><strong>算需求</strong>：客户要什么、要多少、什么时候要 → MRP 展开成采购与生产计划。</li><li><strong>算执行</strong>：单据流驱动采购、生产、库存、销售 → 每一笔都有凭证。</li><li><strong>算钱</strong>：材料 + 人工 + 制造费用 → 成本 → 应收应付 → 总账。</li></ol><p>主链路：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>销售订单 → MRP 运算 → 采购申请 ──► 采购订单 → 到货 → 入库 → 应付</span></span>
<span class="line"><span>                    └► 生产工单 → 领料 → 完工入库 → 成本核算 → 总账</span></span>
<span class="line"><span>销售订单 → 发货 → 出库 → 应收 → 收款 → 应收核销</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="二、核心问题清单" tabindex="-1">二、核心问题清单 <a class="header-anchor" href="#二、核心问题清单" aria-label="Permalink to “二、核心问题清单”">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>核心问题</th><th>为什么难</th><th>典型后果</th></tr></thead><tbody><tr><td>1</td><td><strong>MRP 运算跑不准、跑不动</strong></td><td>多层 BOM 递归展开 + 库存/在途/在制 + 批量与提前期策略</td><td>计划员不信系统，回去手工排</td></tr><tr><td>2</td><td><strong>BOM 变更失控</strong></td><td>工程变更要管版本、生效日期、已下达单据</td><td>车间按旧版 BOM 领料，缺料或报废</td></tr><tr><td>3</td><td><strong>成本算不准</strong></td><td>标准与实际两套账、费用分摊口径、期末在制</td><td>毛利失真，报价拍脑袋</td></tr><tr><td>4</td><td><strong>账实不符</strong></td><td>ERP 账 vs WMS 实物，双份库存</td><td>盘点差异巨大，财务不敢结账</td></tr><tr><td>5</td><td><strong>单据能不能改</strong></td><td>已审核 / 已被下游引用的单据追溯性</td><td>改一张单，后面十张单全错</td></tr><tr><td>6</td><td><strong>期间关账与反关账</strong></td><td>月结后历史数据冻结，跨期调整无出口</td><td>关账后还在补单，成本月月重算</td></tr><tr><td>7</td><td><strong>多组织多工厂内部交易</strong></td><td>法人账 vs 业务账，内部购销与调拨</td><td>集团合并报表对不上</td></tr><tr><td>8</td><td><strong>委外加工</strong></td><td>发料、耗用、损耗、副产物、加工费</td><td>委外库存成了黑洞</td></tr><tr><td>9</td><td><strong>价格与信用管控</strong></td><td>价格政策、折扣、信用额度占用与释放</td><td>超信用发货，坏账</td></tr><tr><td>10</td><td><strong>主数据一致性</strong></td><td>物料/供应商/客户/单位/汇率</td><td>一物多码，报表合并失败</td></tr></tbody></table><h2 id="三、五个深水区逐个拆" tabindex="-1">三、五个深水区逐个拆 <a class="header-anchor" href="#三、五个深水区逐个拆" aria-label="Permalink to “三、五个深水区逐个拆”">​</a></h2><h3 id="_1-mrp-运算-最经典的-算不准" tabindex="-1">1. MRP 运算：最经典的&quot;算不准&quot; <a class="header-anchor" href="#_1-mrp-运算-最经典的-算不准" aria-label="Permalink to “1. MRP 运算：最经典的&quot;算不准&quot;”">​</a></h3><p><strong>问题本质</strong>：MRP 不是一句 SQL 能算完的，它是<strong>按时间分桶的多层净需求推演</strong>。</p><p>单个物料的净需求公式：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>净需求 = 毛需求 + 安全库存 − 现有库存 − 在途(已下达未到货) − 在制(已下达未完工)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>毛需求又分两类：独立需求（销售订单、预测）和相关需求（上层物料展开下来的）。</p><p><strong>第一个坑：同一物料重复展开</strong>。物料 A 既在 BOM 第 2 层、又在第 4 层出现，如果按层级逐层展开，A 的库存会被扣两次，计划量偏小 → 缺料。</p><p>标准解法是<strong>低层码（Low Level Code, LLC）</strong>：取该物料在 BOM 中出现的最深层级作为低层码，按低层码升序逐层展开，每个物料的净需求只算一次。</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>物料 A 出现在 L2 和 L4 → LLC(A) = 4</span></span>
<span class="line"><span>展开顺序：LLC=0 → LLC=1 → ... → LLC=4（A 在最后一次统一结算）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>第二个坑：性能</strong>。十万级 BOM、几万个物料、按天分桶、滚动 90 天，递归 SQL 直接超时。</p><p>工程解法三步：</p><ol><li><strong>BOM 一次性拉到内存建树</strong>（物化路径或父子表 + 缓存），避免数据库递归。</li><li><strong>按低层码分轮次批量计算</strong>，每轮只算当前层的物料，层内可并行。</li><li><strong>运算任务异步化</strong>：提交任务 → 落 <code>mrp_run</code> 主表（running/success/failed）→ 分批写入建议表 → 前端轮询进度。失败可<strong>按物料重跑</strong>，不重跑全量。</li></ol><p><strong>第三个坑：重跑幂等</strong>。同一次运算重复触发，建议单不能翻倍。用 <code>run_id + 物料 + 需求日期</code> 做唯一键，重复即覆盖。</p><blockquote><p><strong>面试口径</strong>：MRP 的技术难点不在公式，在两点——一是用低层码避免同一物料被重复扣库存，二是把&quot;一次跑几小时&quot;拆成&quot;分批可重跑&quot;。计划员不信系统，90% 是因为跑一次太久、结果又没法解释，所以建议单必须能下钻到&quot;这个需求来自哪张订单、扣了哪些库存&quot;。</p></blockquote><h3 id="_2-bom-变更-一张图纸改动-牵出十张单" tabindex="-1">2. BOM 变更：一张图纸改动，牵出十张单 <a class="header-anchor" href="#_2-bom-变更-一张图纸改动-牵出十张单" aria-label="Permalink to “2. BOM 变更：一张图纸改动，牵出十张单”">​</a></h3><p><strong>问题</strong>：ECN（工程变更）下来要换料，但已经下达的工单、已经采购的订单、已经在线的半成品怎么办？</p><p><strong>解法</strong>：BOM 用<strong>版本 + 生效日期 + 生效状态</strong>三重控制。</p><ul><li>变更不覆盖原记录，新增一条版本，<code>effect_date</code> 生效。</li><li>已下达单据<strong>锁定 BOM 版本</strong>（下单时快照 <code>bom_version</code>），不跟随变更漂移。</li><li>尚未开工的工单允许&quot;重新展开&quot;，按新版本重算需求并生成变更单。</li><li>旧料用<strong>替代料</strong>（替代组 + 优先级 + 替代比例）消化，而不是直接删行。</li></ul><blockquote><p><strong>面试口径</strong>：BOM 变更的核心不是&quot;改数据&quot;，是&quot;决定谁跟着变、谁不变&quot;。原则是已发生的不追溯、未发生的可重算，中间用替代料做缓冲。</p></blockquote><h3 id="_3-成本核算-为什么毛利总是对不上" tabindex="-1">3. 成本核算：为什么毛利总是对不上 <a class="header-anchor" href="#_3-成本核算-为什么毛利总是对不上" aria-label="Permalink to “3. 成本核算：为什么毛利总是对不上”">​</a></h3><p><strong>两套账要分清</strong>：</p><table tabindex="0"><thead><tr><th>口径</th><th>用途</th><th>特点</th></tr></thead><tbody><tr><td>标准成本</td><td>报价、预算、差异分析</td><td>年初定，全年不变，稳定</td></tr><tr><td>实际成本</td><td>财务核算、存货计价</td><td>月末结算，随实际发生波动</td></tr></tbody></table><p><strong>差异分析（标准成本法必考）</strong>：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>材料价差 = (实际单价 − 标准单价) × 实际用量     ← 采购部门负责</span></span>
<span class="line"><span>材料量差 = (实际用量 − 标准用量) × 标准单价     ← 生产部门负责</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>期未在制（WIP）怎么处理</strong>：本月投入的材料 + 人工 + 费用，要在&quot;完工入库&quot;和&quot;期末在制&quot;之间分摊。常用约当产量法或按标准成本留存，剩余进完工。这里口径一旦变，毛利就跳。</p><p><strong>存货计价</strong>：移动加权平均（实时、单据级）、月加权平均（月末一次）、先进先出（批次）。ERP 里改计价方式等于重算历史，实施期就必须定死。</p><blockquote><p><strong>面试口径</strong>：成本不准，九成不是算法错，是三个地方漏了——领料没有按工单实际发（用了倒冲但没回写损耗）、制造费用分摊口径每月变、期末在制没留。技术人常忽略的是：成本是<strong>算出来的结果</strong>，源头在 WMS 的领料和 MES 的报工，那两个不准，ERP 怎么算都是错的。</p></blockquote><h3 id="_4-账实不符-erp-和-wms-打起来了" tabindex="-1">4. 账实不符：ERP 和 WMS 打起来了 <a class="header-anchor" href="#_4-账实不符-erp-和-wms-打起来了" aria-label="Permalink to “4. 账实不符：ERP 和 WMS 打起来了”">​</a></h3><p><strong>问题</strong>：两个系统都有库存，谁准？集成后经常出现&quot;ERP 显示有货，仓库找不到&quot;。</p><p><strong>解法</strong>：明确<strong>实物权威源</strong>与<strong>账面权威源</strong>，并且只保留一个可写入方。</p><table tabindex="0"><thead><tr><th>事项</th><th>权威方</th><th>另一方</th></tr></thead><tbody><tr><td>实物数量、库位、批次</td><td>WMS</td><td>ERP 只读</td></tr><tr><td>存货金额、成本、账务</td><td>ERP</td><td>WMS 不参与</td></tr><tr><td>库存调整</td><td>WMS 发起调账单，ERP 审核入账</td><td>双向留痕</td></tr></tbody></table><p>配套两个机制：</p><ul><li><strong>实时回写 + 每日对账</strong>：回写走消息（可靠投递 + 消费幂等），对账跑定时任务比对 <code>物料 + 仓库 + 批次</code> 三元组的数量，差异进异常池。</li><li><strong>不允许双写</strong>：ERP 后台不开放&quot;库存直接修改&quot;功能，所有变动必须有来源单据。</li></ul><blockquote><p><strong>面试口径</strong>：账实不符的技术根因通常有三个——回写消息丢了没人发现、同一个物料两边都能改、单位换算丢精度。所以要有对账任务兜底，且数量字段统一用整数存最小单位（如&quot;件&quot;存到 0.001 用整数放大 1000 倍），不要用 float。</p></blockquote><h3 id="_5-单据能不能改-追溯性的底线" tabindex="-1">5. 单据能不能改：追溯性的底线 <a class="header-anchor" href="#_5-单据能不能改-追溯性的底线" aria-label="Permalink to “5. 单据能不能改：追溯性的底线”">​</a></h3><p><strong>规则</strong>：</p><ul><li>草稿态可改可删。</li><li>已审核未引用：可反审核（需权限 + 留痕）。</li><li>已被下游引用：<strong>禁止反审核</strong>，只能红冲（生成负数单据）+ 重开。</li><li>已关账期间：任何单据不可新增、不可修改，只能在下期做调整单。</li></ul><p><strong>实现要点</strong>：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>凭证不可变（immutable）：单据审核后生成快照 JSON 存 detail_snapshot</span></span>
<span class="line"><span>红冲关系：red_offset_id 指向原单，原单标记 reversed</span></span>
<span class="line"><span>所有操作写 oper_log：谁、何时、改了什么字段、改前改后</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p><strong>面试口径</strong>：财务类系统的第一条铁律是&quot;已发生的事实不能删，只能冲&quot;。技术上就是 insert-only + 状态标记，永不物理删除。这条守住，审计就过得去。</p></blockquote><h2 id="四、面试高频追问" tabindex="-1">四、面试高频追问 <a class="header-anchor" href="#四、面试高频追问" aria-label="Permalink to “四、面试高频追问”">​</a></h2><p><strong>Q1：MRP 为什么不能实时算？</strong> A：实时算意味着每次订单变更都触发全量展开，成本不可接受。工程上是&quot;定时跑 + 关键事件触发局部重算&quot;，比如新增大额订单只重算受影响物料的子树。计划是准实时，不是实时。</p><p><strong>Q2：MRP 结果的准确性怎么保证？</strong> A：三件事——库存和在手单据要实时（至少准实时）、BOM 要准确且版本一致、参数（提前期、批量、安全库存）要有人维护。技术上再加一层：建议单支持&quot;穿透查看&quot;，能点开看到需求来源和扣减明细，计划员才敢用。</p><p><strong>Q3：并发下两个人同时跑 MRP 会怎样？</strong> A：用分布式锁 + run 状态表双重控制。同一时刻只允许一个 running，第二次提交直接返回&quot;运算中&quot;，或者按物料分区加锁允许多实例并行算不同分区。</p><p><strong>Q4：多组织架构怎么设计？</strong> A：三层——法人（Legal Entity）管账、组织（Org）管业务归属、库存组织（Inventory Org）管实物。单据带 <code>org_id</code>，权限按组织隔离。内部交易生成双向单据（一方销售一方采购），价格用内部结算价，合并报表时抵消。</p><p><strong>Q5：金额用什么类型？</strong> A：<code>BigDecimal</code>，数据库 <code>DECIMAL(18,4)</code>~<code>DECIMAL(18,6)</code>，统一舍入模式 <code>HALF_UP</code>，中间计算不四舍五入、只在落库和展示时舍入。绝对不用 <code>double</code>。</p><p><strong>Q6：ERP 和 WMS 的数据同步用同步接口还是消息？</strong> A：写入类用消息（异步、可重试、削峰），查询类用同步接口（要实时结果）。但&quot;库存是否足够&quot;这种校验不能只信异步，要么查 WMS 的实时接口，要么在 ERP 侧维护一份可用的预占量。</p><p><strong>Q7：怎么处理&quot;先发货后开票&quot;的暂估？</strong> A：发货出库时按标准成本或最近采购价做暂估应付，发票到达后做三单匹配（采购单 / 收货单 / 发票），差异走价格差异科目，冲回暂估。</p><h2 id="五、30-秒速答卡" tabindex="-1">五、30 秒速答卡 <a class="header-anchor" href="#五、30-秒速答卡" aria-label="Permalink to “五、30 秒速答卡”">​</a></h2><blockquote><p>ERP 我理解是三层：上面是计划层，MRP 按低层码展开多层 BOM，算出净需求，难点是同一物料不能重复扣库存、以及大 BOM 要分批可重跑；中间是执行层，靠单据流驱动采购生产库存，关键是&quot;已发生不可删只能冲&quot;和期间关账；下面是财务层，标准成本和实际成本两套账，差异拆价差量差，成本准不准取决于 WMS 领料和 MES 报工的数据质量。跨系统上，实物以 WMS 为准、账面以 ERP 为准，靠消息回写加每日对账保证一致。</p></blockquote><hr><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to “关联”">​</a></h2><ul><li><a href="/my-vitepress-site/scenarios/enterprise-digital/">四大系统边界与问题全景</a></li><li><a href="/my-vitepress-site/scenarios/enterprise-digital/wms.html">WMS 核心问题清单</a>（账实不符的另一半在这）</li><li><a href="/my-vitepress-site/scenarios/inventory-deduction.html">库存并发扣减与防超卖</a></li><li><a href="/my-vitepress-site/framework/transaction-propagation.html">事务传播机制</a> · <a href="/my-vitepress-site/scenarios/api-idempotent.html">接口幂等性设计</a></li></ul><p>上一级：<a href="/my-vitepress-site/scenarios/enterprise-digital/">企业数字化</a></p>`,63)])])}const u=s(n,[["render",i]]);export{c as __pageData,u as default};
